import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
public class TempConv extends JFrame {
  JTextField input = new JTextField(8);
  JButton btn = new JButton("转换");
  JLabel result = new JLabel("华氏温度");
  public TempConv() {
    super("温度转换");
    setLayout(new FlowLayout());
    add(input);
    add(btn);
    add(result);
    btn.addActionListener(new ActionListener() {
      public void actionPerformed(ActionEvent e) {
        try {
          String s = input.getText().trim();
          double c = Double.parseDouble(s);
          double f = c * 9 / 5 + 32;
          String t = String.format("%.1f", f);
          result.setText("华氏 " + t + " 度");
        } catch (NumberFormatException ex) {
          result.setText("请输入数字");
        }
      }
    });
    setSize(320, 100);
    setDefaultCloseOperation(EXIT_ON_CLOSE);
    setVisible(true);
  }
  public static void main(String[] args) {
    new TempConv();
  }
}

import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
public class ColorWin extends JFrame {
  JPanel board = new JPanel();
  public ColorWin() {
    super("颜色");
    JPanel top = new JPanel();
    String[] names = {"红色", "绿色", "蓝色"};
    ColorHandler h = new ColorHandler();
    for (int i = 0; i < names.length; i++) {
      JButton b = new JButton(names[i]);
      b.addActionListener(h);
      top.add(b);
    }
    add(top, BorderLayout.NORTH);
    add(board, BorderLayout.CENTER);
    setSize(300, 200);
    setDefaultCloseOperation(EXIT_ON_CLOSE);
    setVisible(true);
  }
  class ColorHandler implements ActionListener {
    public void actionPerformed(ActionEvent e) {
      String cmd = e.getActionCommand();
      Color c = Color.BLUE;
      if (cmd.equals("红色")) c = Color.RED;
      else if (cmd.equals("绿色")) c = Color.GREEN;
      board.setBackground(c);
      setTitle(cmd);
    }
  }
  public static void main(String[] args) {
    new ColorWin();
  }
}

